1	/**
2	 * Tenant shell: resolves the `Actor`, builds the flag snapshot and renders the
3	 * sidebar.
4	 *
5	 * Owner D. Everything below this layout can assume three invariants: an actor
6	 * exists, it belongs to this organization, and the flag snapshot was evaluated
7	 * against that organization's plan. `assertOrgScope()` is what turns the third
8	 * assumption into a guarantee.
9	 *
10	 * Must call (do not reimplement): resolveActorForOrg, snapshotFlags,
11	 * assertOrgScope
12	 */
13	
14	import { notFound } from "next/navigation";
15	import type { ReactNode } from "react";
16	import type { LimitedResource } from "@/types/billing";
17	import { snapshotFlags } from "@/lib/feature-flags";
18	import { getSessionPrincipal } from "@/lib/session";
19	import { assertOrgScope } from "@/lib/tenant";
20	import { checkLimit } from "@/server/services/billing-service";
21	import { buildFlagContext } from "@/server/services/feature-flag-service";
22	import { listNotifications } from "@/server/services/notification-service";
23	import { resolveOrgBySlug } from "@/server/services/organization-service";
24	import { listProjects } from "@/server/services/project-service";
25	import { resolveActorForOrg } from "@/server/services/session-service";
26	import { DashboardShell } from "./_components/dashboard-shell";
27	import { OrgProvider } from "./_components/org-provider";
28	import { UnauthorizedActionError } from "@/actions/_lib/action-errors";
29	
30	type LayoutParams = { orgSlug: string };
31	
32	export const dynamic = "force-dynamic";
33	
34	const SIDEBAR_PROJECT_LIMIT = 12;
35	
36	/** The quota dimensions the shell's usage meters read. */
37	const SHELL_LIMIT_RESOURCES: readonly LimitedResource[] = [
38	  "seats",
39	  "projects",
40	];
41	
42	export default async function Layout(props: {
43	  children: ReactNode;
44	  panel?: ReactNode;
45	  params: Promise<LayoutParams>;
46	}) {
47	  // Next.js 16: params is a Promise and MUST be awaited.
48	  const { orgSlug } = await props.params;
49	
50	  const principal = await getSessionPrincipal();
51	  if (principal === null) {
52	    throw new UnauthorizedActionError();
53	  }
54	
55	  const org = await resolveOrgBySlug(orgSlug);
56	  if (org === null) {
57	    notFound();
58	  }
59	
60	  // A membership the caller does not have resolves to null, which is the same
61	  // 404 as an org that does not exist — see `_lib/tenant-context.ts`.
62	  const actor = await resolveActorForOrg(principal, orgSlug);
63	  if (actor === null) {
64	    notFound();
65	  }
66	  assertOrgScope(actor, org.id);
67	
68	  const flags = snapshotFlags(buildFlagContext(actor, org));
69	
70	  const [projects, notifications, limitChecks] = await Promise.all([
71	    listProjects(actor, { orgId: org.id, limit: SIDEBAR_PROJECT_LIMIT }),
72	    listNotifications(actor, {
73	      orgId: org.id,
74	      recipientId: actor.userId,
75	      unreadOnly: true,
76	      limit: 1,
77	    }),
78	    // Evaluated once per navigation so `usePlanLimits()` in the client tree
